INSERT INTO site_content (id, content) VALUES ('forsale.legal.p1', '1. “AS-IS” SALE AND WARRANTY DISCLAIMER: The Buyer acknowledges and agrees that all equipment, vessels, watercraft, and related gear (collectively, the “Unit”) purchased from the Seller are sold strictly on an “AS-IS, WHERE-IS, AND WITH ALL FAULTS” basis. The Seller makes no representations, promises, or warranties of any kind, express or implied, regarding the condition, design, capacity, performance, merchantability, or fitness for any particular purpose of the Unit. Any and all implied warranties of merchantability or fitness for a particular purpose are expressly disclaimed and excluded from this transaction.') ON CONFLICT (id) DO UPDATE SET content = '1. “AS-IS” SALE AND WARRANTY DISCLAIMER: The Buyer acknowledges and agrees that all equipment, vessels, watercraft, and related gear (collectively, the “Unit”) purchased from the Seller are sold strictly on an “AS-IS, WHERE-IS, AND WITH ALL FAULTS” basis. The Seller makes no representations, promises, or warranties of any kind, express or implied, regarding the condition, design, capacity, performance, merchantability, or fitness for any particular purpose of the Unit. Any and all implied warranties of merchantability or fitness for a particular purpose are expressly disclaimed and excluded from this transaction.', updated_at = now();
INSERT INTO site_content (id, content) VALUES ('forsale.legal.p2', '2. SELLER’S MAINTENANCE REASSURANCE: Notwithstanding the “As-Is” nature of this sale, the Seller takes pride in the operational integrity of its rental fleet. The Seller certifies that during the Unit’s tenure in its rental program, the Unit was subjected to routine care, regular inspections, and professional servicing in accordance with standard company maintenance schedules or as operational needs required.') ON CONFLICT (id) DO UPDATE SET content = '2. SELLER’S MAINTENANCE REASSURANCE: Notwithstanding the “As-Is” nature of this sale, the Seller takes pride in the operational integrity of its rental fleet. The Seller certifies that during the Unit’s tenure in its rental program, the Unit was subjected to routine care, regular inspections, and professional servicing in accordance with standard company maintenance schedules or as operational needs required.', updated_at = now();
INSERT INTO site_content (id, content) VALUES ('forsale.legal.p3', '3. BUYER INSPECTION AND ASSUMPTION OF RISK: The Buyer acknowledges that they have been given a full and fair opportunity to inspect, test, and examine the Unit prior to completing the purchase. By finalizing the sale, the Buyer assumes all risks associated with the use, operation, and future maintenance of the Unit. The Seller shall not be liable for any defects (latent or patent), breakdowns, damages, or injuries resulting from the subsequent operation of the Unit.') ON CONFLICT (id) DO UPDATE SET content = '3. BUYER INSPECTION AND ASSUMPTION OF RISK: The Buyer acknowledges that they have been given a full and fair opportunity to inspect, test, and examine the Unit prior to completing the purchase. By finalizing the sale, the Buyer assumes all risks associated with the use, operation, and future maintenance of the Unit. The Seller shall not be liable for any defects (latent or patent), breakdowns, damages, or injuries resulting from the subsequent operation of the Unit.', updated_at = now();
