INSERT INTO site_content (id, content) VALUES ('forsale.ski26.body', '<strong>Every 2026 ski in our fleet is now $8,950, down from $9,400 and up.</strong> One season on the water with regular service the whole way, factory warranty through July 2027, and ready to pick up today. Expect some minor cosmetic wear, but overall <strong>great condition for rental skis</strong>. Every unit gets a full service before it leaves the dock. A $1,000 deposit holds yours. Call and ask for Cliff.') ON CONFLICT (id) DO UPDATE SET content = '<strong>Every 2026 ski in our fleet is now $8,950, down from $9,400 and up.</strong> One season on the water with regular service the whole way, factory warranty through July 2027, and ready to pick up today. Expect some minor cosmetic wear, but overall <strong>great condition for rental skis</strong>. Every unit gets a full service before it leaves the dock. A $1,000 deposit holds yours. Call and ask for Cliff.', updated_at = now();
